//! The configuration reference: every variable a service reads, rendered from the
//! doc comments it is declared with, so the documentation and the code can't
//! disagree. Declare variables with [`variables!`](crate::variables); a test in each
//! service renders its [`Section`]s and checks the result in as a
//! [`GeneratedFile`].

use super::Variable;
use std::{fmt::Write as _, fs, io, path::PathBuf};
use thiserror::Error;

/// Set to rewrite generated files instead of comparing them; `just docs reference`
/// sets it.
const UPDATE: &str = "UPDATE_DOCS_REFERENCE";

/// Declares environment variables, each a `const` [`Variable`] whose doc comment is
/// also its entry in the configuration reference, then `$list`, all of them in
/// order. `default` names the constant the code falls back to when the variable is
/// unset, which the reference shows. Write the doc comments for operators, without
/// intra-doc links: they are rendered as Markdown outside rustdoc.
///
/// ```
/// sourceorigin_common::variables! {
///     /// Every variable below.
///     const VARIABLES;
///
///     /// Address to listen on.
///     const LISTENER = "APP_LISTENER", default DEFAULT_LISTENER;
///     /// Where users are sent to sign in.
///     const AUTH_ORIGIN = "APP_AUTH_ORIGIN";
/// }
/// const DEFAULT_LISTENER: &str = "127.0.0.1:8080";
///
/// assert_eq!(LISTENER.name(), "APP_LISTENER");
/// assert_eq!(VARIABLES[0].default, Some("127.0.0.1:8080"));
/// assert_eq!(VARIABLES[1].lines, [" Where users are sent to sign in."]);
/// ```
#[macro_export]
macro_rules! variables {
    (
        $(#[$list_meta:meta])* $list_vis:vis const $list:ident;
        $($(#[doc = $doc:literal])+ $vis:vis const $name:ident = $value:literal $(, default $default:ident)?;)+
    ) => {
        $($(#[doc = $doc])+ $vis const $name: $crate::config::Variable = $crate::config::Variable::new($value);)+
        $(#[$list_meta])*
        $list_vis const $list: &[$crate::config::Documented] = &[$($crate::config::Documented {
            variable: $name,
            lines: &[$($doc),+],
            default: $crate::variables!(@default $($default)?),
        }),+];
    };
    (@default) => { None };
    (@default $default:ident) => { Some($default) };
}

/// One variable as the reference lists it.
#[derive(Clone, Copy, Debug)]
pub struct Documented {
    /// The variable.
    pub variable: Variable,
    /// Its declaration's doc comment, one string per line, as rustdoc reads it.
    pub lines: &'static [&'static str],
    /// The value used when it is unset, if the code has one to fall back to.
    pub default: Option<&'static str>,
}

impl Documented {
    /// Renders the variable as a list item: its name, its description, and its
    /// default. A blank doc comment line starts a new paragraph.
    fn render(&self, out: &mut String) {
        let mut paragraphs: Vec<String> = vec![String::new()];
        for line in self.lines {
            let line = line.strip_prefix(' ').unwrap_or(line).trim_end();
            if line.is_empty() {
                paragraphs.push(String::new());
            } else if let Some(paragraph) = paragraphs.last_mut() {
                if !paragraph.is_empty() {
                    paragraph.push(' ');
                }
                paragraph.push_str(line);
            }
        }
        paragraphs.retain(|paragraph| !paragraph.is_empty());
        if let Some(default) = self.default {
            let sentence = format!("Default: `{default}`.");
            match paragraphs.last_mut() {
                Some(last) => {
                    last.push(' ');
                    last.push_str(&sentence);
                }
                None => paragraphs.push(sentence),
            }
        }
        let _ = write!(out, "- `{}`:", self.variable.name());
        for (index, paragraph) in paragraphs.iter().enumerate() {
            if index == 0 {
                let _ = writeln!(out, " {paragraph}");
            } else {
                let _ = writeln!(out, "\n  {paragraph}");
            }
        }
    }
}

/// A titled group of variables, such as a service's database settings.
#[derive(Clone, Copy, Debug)]
pub struct Section {
    /// The section's heading.
    pub title: &'static str,
    /// Its variables, in the order they are listed.
    pub variables: &'static [Documented],
}

impl Section {
    /// Renders `sections` as a Markdown fragment, each under a heading of `level`,
    /// with the comment saying where it comes from and how to regenerate it.
    #[must_use]
    pub fn render(sections: &[Self], level: usize, source: &str) -> String {
        let mut out = format!(
            "<!-- Generated by `just docs reference` from {source}. Do not edit it by hand. -->\n"
        );
        for section in sections {
            let _ = writeln!(out, "\n{} {}\n", "#".repeat(level), section.title);
            for variable in section.variables {
                variable.render(&mut out);
            }
        }
        out
    }
}

/// A generated documentation file, which is committed to the repository.
#[derive(Debug)]
pub struct GeneratedFile {
    /// Where it is committed.
    pub path: PathBuf,
    /// What it should contain.
    pub text: String,
}

impl GeneratedFile {
    /// Writes the file when `UPDATE_DOCS_REFERENCE` is set. Otherwise compares it
    /// with the committed one, so a test fails while the committed file is stale.
    ///
    /// # Errors
    /// Returns [`Stale`] when the committed file differs, or the write's error.
    pub fn write_or_compare(&self) -> Result<(), Stale> {
        if std::env::var_os(UPDATE).is_some() {
            return fs::write(&self.path, &self.text).map_err(|source| Stale::Write {
                path: self.path.clone(),
                source,
            });
        }
        match fs::read_to_string(&self.path) {
            Ok(committed) if committed == self.text => Ok(()),
            _ => Err(Stale::Differs {
                path: self.path.clone(),
            }),
        }
    }
}

/// Why a generated file doesn't match its source.
#[derive(Debug, Error)]
pub enum Stale {
    /// The committed file differs from what its source renders, or is missing.
    #[error("{} is stale; run `just docs reference`", path.display())]
    Differs {
        /// The committed file.
        path: PathBuf,
    },
    /// Rewriting it failed.
    #[error("cannot write {}", path.display())]
    Write {
        /// The file being written.
        path: PathBuf,
        /// The write's failure.
        #[source]
        source: io::Error,
    },
}
